"""report.py — F5: the one-page operations report for the cell version (2026-11-02; discipline 15).

Reads the recorded shift (factory/ops/results/<shift>.json + runs/<shift>/kpis.jsonl), the operating-envelope sweep
(factory/ops/results/f5-sweep.json) and the earlier phases' evaluations (F2, F3, F4), and writes
docs/ops/F5-operations-report.md and docs/media/F5-operations-report.png: the numbers and the trade-offs.

    envs/mj/bin/python -I factory/ops/report.py [--shift f5-shift]
"""
import argparse, json, os, sys, time
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__)); FACTORY = os.path.dirname(HERE); ROOT = os.path.dirname(FACTORY)
MEDIA = os.path.join(ROOT, "docs", "media"); OPS = os.path.join(ROOT, "docs", "ops")


def load(p):
    p = os.path.join(ROOT, p); return json.load(open(p)) if os.path.exists(p) else None


def figure(shift, rows, sweep, path):
    import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
    fig, ax = plt.subplots(1, 3, figsize=(17, 4.6))
    t = [r["t"] / 60 for r in rows]; ax[0].plot(t, [r["sorted_last_min"] for r in rows], color="#2f6db5", lw=2, label="sorted in the last minute")
    ax[0].plot(t, [r["arrived"] / max(r["t"] / 60, 1e-6) for r in rows], color="#999", lw=1, ls="--", label="arrived per minute (cumulative)")
    a2 = ax[0].twinx(); a2.plot(t, [r["oee"] for r in rows], color="#d9822b", lw=1.5, label="OEE"); a2.set_ylim(0, 1); a2.set_ylabel("OEE")
    ax[0].set_xlabel("shift time, min"); ax[0].set_ylabel("items per minute"); ax[0].set_title(f"The shift: {shift['config']['minutes']:g} min, {shift['config']['speed']} m/s, {shift['config']['rate']:g}/min, clutter {shift['config']['clutter']:.0%}")
    h1, l1 = ax[0].get_legend_handles_labels(); h2, l2 = a2.get_legend_handles_labels(); ax[0].legend(h1 + h2, l1 + l2, fontsize=8, loc="lower right")
    f = shift["final"]; loss = dict(f["losses"]); loss = {k: v for k, v in sorted(loss.items(), key=lambda kv: -kv[1]) if v}
    ax[1].barh(["sorted"] + list(loss), [f["sorted"]] + list(loss.values()), color=["#16a34a"] + ["#c2410c"] * len(loss)); ax[1].invert_yaxis()
    ax[1].set_title(f"Where the {f['arrived']} items went (A {f['availability']:.0%} · P {f['performance']:.0%} · Q {f['quality']:.0%} · OEE {f['oee']:.0%})"); ax[1].set_xlabel("items")
    if sweep:
        for c, ls in ((0.0, "-"), (0.25, "--")):
            for sp, col in ((0.15, "#2f6db5"), (0.3, "#d9822b"), (0.5, "#7c3aed")):
                rr = sorted([r for r in sweep["rows"] if r["speed"] == sp and r["clutter"] == c], key=lambda r: r["rate"])
                if rr: ax[2].plot([r["rate"] for r in rr], [r["sorted_per_min"] for r in rr], ls, marker="o", color=col, label=f"{sp} m/s{', clutter' if c else ''}")
        ax[2].set_xlabel("arrivals per minute"); ax[2].set_ylabel("sorted per minute"); ax[2].legend(fontsize=8, ncol=2); ax[2].set_title("Operating envelope of this cell (" + sweep.get("_source", "f5-sweep.json") + ", 2 seeds x 180 s)", fontsize=9)
    fig.tight_layout(); fig.savefig(path, dpi=110)


def main():
    p = argparse.ArgumentParser(); p.add_argument("--shift", default="f5-shift"); a = p.parse_args()
    shift = load(f"factory/ops/results/{a.shift}.json"); assert shift, f"no recorded shift {a.shift}: run rl shift run first"
    kp = os.path.join(ROOT, "runs", a.shift, "kpis.jsonl")
    if not os.path.exists(kp) and a.shift == "f5-shift": kp = os.path.join(ROOT, "docs", "results", "f5", "kpis.jsonl")   # the shipped copy
    rows = [json.loads(l) for l in open(kp)]
    sweep = load("factory/ops/results/f5-sweep.json")
    if sweep is None:   # the F5 cell's envelope was swept in F7 as "v1" (same cell, same sweep.py)
        sweep = load("factory/ops/results/f7-sweep-v1.json")
        if sweep: sweep["_source"] = "measured in F7 as v1"
    f2 = load("factory/line/results/f2-eval.json"); f3 = load("factory/learned/results/f3-eval.json"); f4 = load("factory/vision/results/f4-eval.json")
    cp = load("factory/vision/results/f5-clutter-perception.json")
    clut = f"both items named in {cp['split']['both_named']} of {cp['scenes']} touching pairs on a stopped belt, {cp['no_split']['both_named']} without the split" if cp else "not measured"
    os.makedirs(OPS, exist_ok=True); png = os.path.join(MEDIA, "F5-operations-report.png"); figure(shift, rows, sweep, png)
    f = shift["final"]; c = shift["config"]; mins = c["minutes"]; S = shift["summary"]
    L = [f"# Operations report: sorting cell v5 (F5), {time.strftime('%Y-%m-%d')}", "",
         "Generated by `factory/ops/report.py` from recorded runs (simulation, not a real cell). One page: what the cell is, what one",
         "shift did, where it loses items, and the trade-offs between speed, load and reliability.", "",
         "![the shift, the losses, the envelope](../media/F5-operations-report.png)", "",
         "## The cell", "",
         "UR5e + Robotiq 2F-85 with a suction cup for flat boxes (hybrid tool), a 0.4 m belt, three chutes (plastic, metal,",
         "cardboard), one overhead Intel RealSense D435i. Perception: depth blobs, kNN identity, Kalman tracks (F4); the robot",
         "never reads the simulator's poses. Grasp, intercept and lift: classical (F1, F2). Carry: the learned policy in its",
         "vision-only student form (F3, F4). Safety: protective stops on contact or tracking error, recovery and retry (F2).", "",
         f"## The shift ({mins:g} minutes of continuous running, {shift['date']})", "",
         f"Belt {c['speed']} m/s, {c['rate']:g} arrivals per minute at random, {c['clutter']:.0%} of them as two touching items, perception: {c['perception']}, carry: {c['carry']}.", "",
         "| KPI | value | definition |", "|---|---|---|",
         f"| throughput | **{f['sorted_per_min']:.1f} sorted/min** ({60 * f['sorted_per_min']:.0f}/h) | items in the right chute per minute |",
         f"| sort rate | {f['sort_rate']:.0%} ({f['sorted']} of {f['arrived']}) | sorted / items that arrived and left |",
         f"| availability | {f['availability']:.0%} | share of the shift not stopped or recovering |",
         f"| performance | {f['performance']:.0%} | items handled (picked at least once) / arrived: what capacity let through |",
         f"| quality | {f['quality']:.0%} | sorted / handled |",
         f"| **OEE** | **{f['oee']:.0%}** | availability x performance x quality |",
         f"| cycle | {f['cycle_s']} s | per successful pick (decide, intercept, grasp, lift, carry, release) |",
         f"| protective stops | {f['protective_stops']} | contact with a fixture or a joint far behind its reference |", "",
         "Losses: " + ", ".join(f"{k.replace('_', ' ')} {v}" for k, v in f["losses"].items()) + f". Robot events: " + ", ".join(f"{k} {v}" for k, v in f["events"].items()) + ".",
         f"Items that arrived in touching pairs: " + ", ".join(f"{k} {v}" for k, v in shift.get("clutter_items", {}).items()) + ".", ""]
    biggest = max(f["losses"], key=f["losses"].get) if any(f["losses"].values()) else None
    cap = 60.0 / f["cycle_s"] if f.get("cycle_s") else None
    L += ["## What limits it", ""]
    if biggest: L += [f"- The largest loss is **{biggest.replace('_', ' ')}** ({f['losses'][biggest]} of {f['arrived']}). " + (
        f"With a {f['cycle_s']} s cycle one arm could sort up to ~{cap:.0f} items/min, and on average it was busy only {sum(f['events'].values()) * f['cycle_s'] / (60 * mins):.0%} of the shift: "
        "items are missed in bursts, when random arrivals and touching pairs put two or three items in the zone within one cycle. "
        "Availability and quality are high; performance is the gap." if biggest == "missed" and cap else "")]
    if sweep:
        def row(s, r, cl): return next((x for x in sweep["rows"] if x["speed"] == s and x["rate"] == r and x["clutter"] == cl), None)
        L += ["", "## The operating envelope (vision + student carry, 180 s per run, " + f"{sweep['seeds']} seeds per point)", "",
              "| belt | arrivals/min | clutter | sorted/min | sort rate | attempt success | cycle s | protective stops |", "|---|---|---|---|---|---|---|---|"]
        for x in sweep["rows"]: L.append(f"| {x['speed']} m/s | {x['rate']:g} | {x['clutter']:.0%} | {x['sorted_per_min']} | {x['sort_rate']:.0%} | {x['attempt_success']} | {x['cycle_s']} | {x['protective_stops']} |")
        best = max(sweep["rows"], key=lambda x: x["sorted_per_min"]); L += ["", f"Highest throughput in the sweep: {best['sorted_per_min']} sorted/min at {best['speed']} m/s, {best['rate']:g}/min, clutter {best['clutter']:.0%} (sort rate {best['sort_rate']:.0%})."]
    L += ["", "## The cell's versions (L2: 16 random arrivals/min, all 11 items; sorted per minute, mean over seeds)", "", "| version | 0.15 m/s | 0.30 m/s | source |", "|---|---|---|---|"]
    if f3:
        t = f3["table"]; g = lambda k: t.get(k, {}).get("sorted_per_min")
        L.append(f"| F2 classical, privileged poses | {g('mixed · 0.15 m/s · 16/min · f2')} | {g('mixed · 0.30 m/s · 16/min · f2')} | F3 evaluation, F2 arm |")
        L.append(f"| F3 learned carry, privileged poses | {g('mixed · 0.15 m/s · 16/min · learned')} | {g('mixed · 0.30 m/s · 16/min · learned')} | `factory/learned/results/f3-eval.json` |")
    if f4:
        t = f4["table"]; g = lambda k: t.get(k, {}).get("sorted_per_min")
        L.append(f"| F4 vision only, F2 carry | {g('0.15 m/s · L4-f2')} | {g('0.30 m/s · L4-f2')} | `factory/vision/results/f4-eval.json` |")
        L.append(f"| F4 vision only, student carry (this cell) | {g('0.15 m/s · L4')} | {g('0.30 m/s · L4')} | same |")
    L += ["", "## Trade-offs", "",
          "- **Belt speed vs reliability.** A faster belt brings items through the reach zone sooner, so each one is reachable for less time: at the same arrival rate more pass unpicked (performance falls) while what is picked still lands (quality stays). The fast belt (0.5 m/s) is where the intercept and the tracking budget get tight (F2's tracking study: 14-26 mm prediction error at 0.5 m/s against 7-10 mm at 0.3).",
          "- **Load vs throughput.** Throughput rises with arrivals until the arm saturates near one item per cycle, then the extra items are simply missed. Running the belt at the saturation load maximises sorted/min; running below it maximises sort rate. Which one matters is a business decision (value of a sorted item vs cost of a missed one).",
          f"- **Clutter.** Touching pairs cost twice: perception has to split them ({clut}), and two items arriving together compete for one arm. A singulating conveyor upstream, or a second arm, buys back most of it.",
          "- **Learning vs engineering.** The learned carry bought most of the throughput gain over F2 (shorter cycle by releasing in flight); vision cost little on top, because the classical perception is accurate on separated items (2.4 mm, 100% identity in simulation). Real cameras add noise, glare and motion blur that the simulation does not have: the sim-to-real gap (discipline 14) is the next risk, not the algorithm.",
          "- **What to buy next.** Capacity is the binding constraint: a second arm (F5 optional) or a shorter cycle (a faster carry, a better scheduler) converts misses into sorted items; quality and availability are already near their ceilings.", "",
          "Sources: " + ", ".join(f"`{x}`" for x in [f"factory/ops/results/{a.shift}.json", f"runs/{a.shift}/kpis.jsonl", "factory/ops/results/f5-sweep.json", "factory/learned/results/f3-eval.json", "factory/vision/results/f4-eval.json"] if os.path.exists(os.path.join(ROOT, x))) + "."]
    out = os.path.join(OPS, "F5-operations-report.md"); open(out, "w").write("\n".join(L) + "\n"); print(out, png)


if __name__ == "__main__":
    main()
